---@field host? table The host seams: transport, sleep, now, exec, random, getenv, epoch
---@field transport? fun(request: table): (table?, distilled.Error?)
---@field sleep? fun(seconds: number)
---@field now? fun(): number
---@field retry? string|table A retry preset or policy fields
---@field deadline_s? number Wall-clock budget for one call, sleeps included
---@field tracing? "off"|"operation"|"debug"|table
---@field validation? "lenient"|"additional"|"strict"
---@field [string] any

---@class cloudflare.email_sending.Module
local Module = {}

---@param options? cloudflare.email_sending.Options
---@return cloudflare.email_sending.Client
function Module.new(options) end

---@class cloudflare.email_sending.Client
local Client = {}

---A client sharing this one's budget, credentials cache and tracer, with overrides.
---@param options cloudflare.email_sending.Options
---@return cloudflare.email_sending.Client
function Client:with(options) end

---Flush spans and release what the client holds.
function Client:close() end

---Creates a new sending subdomain or re-enables sending on an existing subdomain that had it disabled. If zone-level Email Sending has not been enabled yet, the zone flag is automatically set when the entitlement is present. A leftmost wildcard such as `*.example.com` is accepted only for accounts with wildcard Email Sending enabled. Wildcard senders share the base domain's DKIM signing identity and `cf-bounce.<base>` return path.
---
---`POST /zones/{zone_id}/email/sending/subdomains`
---Errors: Forbidden, SendingSubdomainAlreadyExists.
---@param input cloudflare.email_sending.CreateSubdomainRequest
---@return cloudflare.email_sending.CreateSubdomainResponse? value
---@return distilled.Error? err
function Client:create_subdomain(input) end

---Creates a suppression for every sending domain of the account (default) or for one sending domain (`scope.type = sending_domain`). Creating an existing active suppression returns its identifier. If a mutable legacy zone-linked account row already exists, it is promoted without changing its identifier.
---
---`POST /accounts/{account_id}/email/sending/suppressions`
---@param input cloudflare.email_sending.CreateSuppressionRequest
---@return cloudflare.email_sending.CreateSuppressionResponse? value
---@return distilled.Error? err
function Client:create_suppression(input) end

---Disables sending on a subdomain and removes its DNS records. If routing is still active on the subdomain, only sending is disabled.
---
---`DELETE /zones/{zone_id}/email/sending/subdomains/{subdomain_id}`
---Errors: Forbidden, SendingSubdomainNotFound.
---@param input cloudflare.email_sending.DeleteSubdomainRequest
---@return cloudflare.email_sending.DeleteSubdomainResponse? value
---@return distilled.Error? err
function Client:delete_subdomain(input) end

---Deletes the suppression, its note, and every legacy internal zone membership, allowing future delivery attempts to the address.
---
---`DELETE /accounts/{account_id}/email/sending/suppressions/{suppression_id}`
---@param input cloudflare.email_sending.DeleteSuppressionRequest
---@return cloudflare.email_sending.DeleteSuppressionResponse? value
---@return distilled.Error? err
function Client:delete_suppression(input) end

---Updates the activity-log preview preference for a sending subdomain.
---
---`PATCH /zones/{zone_id}/email/sending/subdomains/{subdomain_id}`
---@param input cloudflare.email_sending.EditSubdomainRequest
---@return cloudflare.email_sending.EditSubdomainResponse? value
---@return distilled.Error? err
function Client:edit_subdomain(input) end

---Updates expiry or advisory note fields without changing legacy internal zone memberships. Scope cannot be changed.
---
---`PATCH /accounts/{account_id}/email/sending/suppressions/{suppression_id}`
---@param input cloudflare.email_sending.EditSuppressionRequest
---@return cloudflare.email_sending.EditSuppressionResponse? value
---@return distilled.Error? err
function Client:edit_suppression(input) end

---Gets information for a specific sending subdomain.
---
---`GET /zones/{zone_id}/email/sending/subdomains/{subdomain_id}`
---Errors: Forbidden, SendingSubdomainNotFound.
---@param input cloudflare.email_sending.GetSubdomainRequest
---@return cloudflare.email_sending.GetSubdomainResponse? value
---@return distilled.Error? err
function Client:get_subdomain(input) end

---Returns the expected DNS records for a sending subdomain.
---
---`GET /zones/{zone_id}/email/sending/subdomains/{subdomain_id}/dns`
---@param input cloudflare.email_sending.GetSubdomainDnsRequest
---@return cloudflare.email_sending.GetSubdomainDnsResponse? value
---@return distilled.Error? err
function Client:get_subdomain_dns(input) end

---Returns the expected DNS records for a sending subdomain.
---
---Every page, fetched as the loop asks for it.
---
---`GET /zones/{zone_id}/email/sending/subdomains/{subdomain_id}/dns`
---@param input cloudflare.email_sending.GetSubdomainDnsRequest
---@return distilled.Iterator<cloudflare.email_sending.GetSubdomainDnsResponse>
function Client:get_subdomain_dns_pages(input) end

---Returns the expected DNS records for a sending subdomain.
---
---Every item of every page (`result`).
---
---`GET /zones/{zone_id}/email/sending/subdomains/{subdomain_id}/dns`
---@param input cloudflare.email_sending.GetSubdomainDnsRequest
---@return distilled.Iterator<cloudflare.email_sending.SubdomainsDnsGetResultItem>
function Client:get_subdomain_dns_items(input) end

---Gets an Email Sending suppression owned by the account.
---
---`GET /accounts/{account_id}/email/sending/suppressions/{suppression_id}`
---@param input cloudflare.email_sending.GetSuppressionRequest
---@return cloudflare.email_sending.GetSuppressionResponse? value
---@return distilled.Error? err
function Client:get_suppression(input) end

---Imports up to 1,000 Email Sending suppressions in one request. Each item applies to every sending domain of the account (default) or to one sending domain.
---
---`POST /accounts/{account_id}/email/sending/suppressions/bulk`
---@param input cloudflare.email_sending.ImportSuppressionRequest
---@return cloudflare.email_sending.ImportSuppressionResponse? value
---@return distilled.Error? err
function Client:import_suppression(input) end

---Lists all sending-enabled subdomains for the zone.
---
---`GET /zones/{zone_id}/email/sending/subdomains`
---Errors: Forbidden.
---@param input cloudflare.email_sending.ListSubdomainsRequest
---@return cloudflare.email_sending.ListSubdomainsResponse? value
---@return distilled.Error? err
function Client:list_subdomains(input) end

---Lists all sending-enabled subdomains for the zone.
---
---Every page, fetched as the loop asks for it.
---
---`GET /zones/{zone_id}/email/sending/subdomains`
---Errors: Forbidden.
---@param input cloudflare.email_sending.ListSubdomainsRequest
---@return distilled.Iterator<cloudflare.email_sending.ListSubdomainsResponse>
function Client:list_subdomains_pages(input) end

---Lists all sending-enabled subdomains for the zone.
---
---Every item of every page (`result`).
---
---`GET /zones/{zone_id}/email/sending/subdomains`
---Errors: Forbidden.
---@param input cloudflare.email_sending.ListSubdomainsRequest
---@return distilled.Iterator<cloudflare.email_sending.SubdomainsListResultItem>
function Client:list_subdomains_items(input) end

---Lists every active Email Sending suppression owned by the account: sending-domain suppressions first, then account-wide suppressions (including legacy rows with internal zone memberships). Each group is newest first.
---
---`GET /accounts/{account_id}/email/sending/suppressions`
---@param input cloudflare.email_sending.ListSuppressionsRequest
---@return cloudflare.email_sending.ListSuppressionsResultList? value
---@return distilled.Error? err
function Client:list_suppressions(input) end

---Send an email for the specified account using the structured builder. Provide the sender, recipients, subject, and at least one of text or html; attachments are optional.
---
---`POST /accounts/{account_id}/email/sending/send`
---@param input cloudflare.email_sending.SendEmailSendingRequest
---@return cloudflare.email_sending.SendEmailSendingResponse? value
---@return distilled.Error? err
function Client:send_email_sending(input) end

---Send a raw RFC 5322 (MIME) email for the specified account. Provide the full MIME message plus the SMTP envelope (from and recipients).
---
---`POST /accounts/{account_id}/email/sending/send_raw`
---@param input cloudflare.email_sending.SendRawEmailSendingRequest
---@return cloudflare.email_sending.SendRawEmailSendingResponse? value
---@return distilled.Error? err
function Client:send_raw_email_sending(input) end

return Module
